-- Tabela de Datas
SELECT TO_CHAR(d, 'YYYYMMDD')::INT, d::DATE, EXTRACT(YEAR FROM d), EXTRACT(MONTH FROM d), EXTRACT(DAY FROM d), TO_CHAR(d, 'TMDy'), CASE WHEN EXTRACT(ISODOW FROM d) IN (6, 7) THEN TRUE ELSE FALSE END, FALSE FROM generate_series('2023-01-01'::DATE, '2025-12-31'::DATE, '1 day'::INTERVAL) AS d;

